"use strict";(globalThis.webpackChunkgrc||=[]).push([[65984],{25882(e){e.exports=JSON.parse('{"citeKey":"kougkas2020bridgingstorage","slug":"kougkas-2020-bridging-storage-5e1c","title":"Bridging Storage Semantics using Data Labels and Asynchronous I/O","authors":["A. Kougkas","H. Devarajan","X.-H. Sun"],"venue":"ACM Transactions on Storage (TOS\'20), Vol 16, No 4, Article 22, Nov. 2020","type":"Journal","entryType":"article","date":"November, 2020","year":2020,"era":"iit","month":11,"doi":"10.1145/3415579","abstract":"In the era of data-intensive computing, large-scale applications, in both scientific and the BigData communities, demonstrate unique I/O requirements leading to a proliferation of different storage devices and software stacks, many of which have conflicting requirements. Further, new hardware technologies and system designs create a hierarchical composition that may be ideal for computational storage operations. In this paper, we investigate how to support a wide variety of conflicting I/O workloads under a single storage system. We introduce the idea of a Label, a new data representation, and, we present LABIOS: a new, distributed, Label- based I/O system. LABIOS boosts I/O performance by up to 17x via asynchronous I/O, supports heterogeneous storage resources, offers storage elasticity, and promotes in-situ analytics and software defined storage support via data provisioning. LABIOS demonstrates the effectiveness of storage bridging to support the convergence of HPC and BigData workloads on a single platform.","hasAbstract":true,"lede":"Further, new hardware technologies and system designs create a hierarchical composition that may be ideal for computational storage operations.","links":{"pdf":"https://grc.iit.edu/papers/2020/kougkas-2020-bridging-storage-5e1c.pdf"},"tags":["Label-Based I/O","Storage Bridging","Heterogeneous I/O","Datalabels","Task-Based I/O","Exascale I/O","Energy-Aware I/O","Elastic Storage"],"_projectIds":["hermes","iris"],"grcSelected":false,"status":"published","visibility":"public","projectIds":["labios","hermes","iris"],"memberAuthors":["kougkas-anthony","devarajan-hariharan","sun-xian-he"],"funding":[{"agency":"NSF","award":"OAC-1835764","projectId":"hermes"},{"agency":"NSF","award":"CSR-1814872","projectId":"iris"}]}')}}]);